import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"住居と環境保障","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0039-住房与环境保障.md","filePath":"ja/0039-住房与环境保障.md"}'),i={name:"ja/0039-住房与环境保障.md"};function n(e,t,d,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="住居と環境保障" tabindex="-1">住居と環境保障 <a class="header-anchor" href="#住居と環境保障" aria-label="Permalink to &quot;住居と環境保障&quot;">​</a></h1><table tabindex="0"><thead><tr><th>プロジェクト</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>39</td></tr><tr><td>所属モジュール</td><td>文明類型と社会制度</td></tr><tr><td>コアキーワード</td><td>住居保障、環境保護、生態共生、居住可能空間、持続可能な発展</td></tr></tbody></table><h2 id="第一節-住居と環境保障の核心理念" tabindex="-1">第一節 住居と環境保障の核心理念 <a class="header-anchor" href="#第一節-住居と環境保障の核心理念" aria-label="Permalink to &quot;第一節 住居と環境保障の核心理念&quot;">​</a></h2><p>「居住者にはその家がある」は、すべての文明が直面しなければならない基本的な民生問題である。略奪式修練体系の時代には、住居と土地は少数の強者と宗派によって独占され、底辺の衆生はしばしば住む場所がなく、劣悪な環境で修練と生活を強いられた。さらに深刻なのは、略奪式修練が環境に巨大な破壊をもたらしたことである——霊脈が過度に採掘され、生態系が深刻に汚染され、惑星資源が略奪式に消費され、かつて居住可能だった多くの惑星が荒れ地に変わった。</p><p>アンカー共生文明が樹立された後、住居保障と環境保護は社会制度建設の核心的内容とされた。住居と環境保障の核心理念は「居住者に家あり、生態共生、持続可能な発展、万族居住可能」の十六文字に要約できる。</p><p>住居と環境保障の核心目標には以下が含まれる：</p><ol><li><strong>基本居住権の保障</strong>：すべての共生生命が尊厳ある、安全で適切な住居を獲得できることを確保し、住居問題が生存と進化に影響を与えないようにする</li><li><strong>生態環境の保護</strong>：完備した環境保護体系を構築し、生態平衡を維持し、修練活動による環境破壊を防止する</li><li><strong>居住可能空間の建設</strong>：科学的な計画と技術的手段により、修練と生活に適した居住可能空間を建設する</li><li><strong>持続可能な発展の実現</strong>：現世代の需要を満たすと同時に、後世代が自身の需要を満たす能力を損なわず、資源環境の持続可能な利用を実現する</li><li><strong>万族居住可能の促進</strong>：住居と環境建設において異なる種族の生理的特徴と生活習慣を十分に考慮し、万族すべてが居住可能であることを確保する</li></ol><h2 id="第二節-住居保障体系" tabindex="-1">第二節 住居保障体系 <a class="header-anchor" href="#第二節-住居保障体系" aria-label="Permalink to &quot;第二節 住居保障体系&quot;">​</a></h2><p>共生文明の住居保障体系は「基本を保障し、改善を促進し、多ルート、持続可能」の原則に従い、多層次の住居供給体系を構築している：</p><h3 id="_2-1-住居供給の三つの層次" tabindex="-1">2.1 住居供給の三つの層次 <a class="header-anchor" href="#_2-1-住居供給の三つの層次" aria-label="Permalink to &quot;2.1 住居供給の三つの層次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>層次</th><th>名称</th><th>供給対象</th><th>住居タイプ</th><th>賃料/販売価格</th></tr></thead><tbody><tr><td>第一層次</td><td>保障房</td><td>低所得層、新米修練者</td><td>基礎修練アパート、集団寮</td><td>無料または極低賃料</td></tr><tr><td>第二層次</td><td>改善房</td><td>中所得層、中級修練者</td><td>標準修練住宅、家族アパート</td><td>原価または低賃料</td></tr><tr><td>第三層次</td><td>商品房</td><td>高所得層、高級修練者</td><td>高級修練住宅、独立洞府</td><td>市場価格</td></tr></tbody></table><h3 id="_2-2-保障房制度" tabindex="-1">2.2 保障房制度 <a class="header-anchor" href="#_2-2-保障房制度" aria-label="Permalink to &quot;2.2 保障房制度&quot;">​</a></h3><p>保障房は住居保障体系の核心であり、すべての共生生命の基本居住権を保障する：</p><ul><li><strong>基礎修練アパート</strong>：新米修練者と独身者向けの小型アパート、基礎修練施設を備え、賃料は極低または無料</li><li><strong>集団寮</strong>：宗派の弟子、学生、集団労働者向けの集団住宿、公共修練空間を備える</li><li><strong>家族保障房</strong>：低所得家族向けの成套住宅、面積は適度で、付帯施設は完備</li><li><strong>特殊保障房</strong>：障害のある生命、特殊種族、高齢修練者などの特殊集団向けの適応性住居</li></ul><p>保障房の申請と配分は「公開、公平、公正」の原則に従い、共生ネットワークを通じて申請と審査を行い、配分結果は公開透明である。</p><h3 id="_2-3-改善房制度" tabindex="-1">2.3 改善房制度 <a class="header-anchor" href="#_2-3-改善房制度" aria-label="Permalink to &quot;2.3 改善房制度&quot;">​</a></h3><p>改善房は一定の経済力を持つ中所得層向けで、原価または低賃料で提供される：</p><ul><li><strong>標準修練住宅</strong>：独立修練室を備えた成套住宅、一定の修練基礎を持つ個人と家族に適する</li><li><strong>家族アパート</strong>：家族居住に適した中型アパート、児童活動空間と家族修練エリアを備える</li><li><strong>人材アパート</strong>：導入された高級人材と専門技術者向けの優遇住居</li></ul><p>改善房の供給量は需要に応じて動的に調整され、中所得層が合理的なコストで適切な住居を獲得できることを確保する。</p><h3 id="_2-4-商品房制度" tabindex="-1">2.4 商品房制度 <a class="header-anchor" href="#_2-4-商品房制度" aria-label="Permalink to &quot;2.4 商品房制度&quot;">​</a></h3><p>商品房は高所得層向けで、市場価格で提供される：</p><ul><li><strong>高級修練住宅</strong>：高級修練施設を備えた豪華住宅</li><li><strong>独立洞府</strong>：独立空間とエネルギー供給を持つ修練洞府</li><li><strong>カスタム住宅</strong>：個人の需要に応じてカスタマイズされた特殊住宅</li></ul><p>商品房の取引は市場ルールに従うが、政府は不動産税、土地管理などの手段を通じて調整を行い、住宅価格の過度な上昇と不動産投機を防止する。</p><h3 id="_2-5-修練空間付帯施設" tabindex="-1">2.5 修練空間付帯施設 <a class="header-anchor" href="#_2-5-修練空間付帯施設" aria-label="Permalink to &quot;2.5 修練空間付帯施設&quot;">​</a></h3><p>共生文明の住居は単なる居住空間ではなく、修練空間でもある。各住居は居住者の修練需要に応じて、対応する修練施設を備えている：</p><ul><li><strong>基礎修練エリア</strong>：各住居には基礎修練エリアが設けられ、基礎エネルギー接続インターフェースを備える</li><li><strong>エネルギー供給</strong>：アンカーネットワークを通じて住居に安定したエネルギー供給を提供し、修練需要を満たす</li><li><strong>防音防護</strong>：修練エリアには防音とエネルギー防護施設が設けられ、修練が他人を妨害することを防止する</li><li><strong>公共修練空間</strong>：コミュニティには公共修練ホール、修練器材室などの共有空間が設けられている</li></ul><h2 id="第三節-環境保護体系" tabindex="-1">第三節 環境保護体系 <a class="header-anchor" href="#第三節-環境保護体系" aria-label="Permalink to &quot;第三節 環境保護体系&quot;">​</a></h2><p>共生文明の環境保護体系は「予防を主とし、総合治理し、生態修復し、持続可能に利用する」の原則に従い、全方位の環境保護フレームワークを構築している：</p><h3 id="_3-1-環境基準と監管" tabindex="-1">3.1 環境基準と監管 <a class="header-anchor" href="#_3-1-環境基準と監管" aria-label="Permalink to &quot;3.1 環境基準と監管&quot;">​</a></h3><p>共生文明は厳格な環境基準を制定し、修練活動と生産活動の環境影響を規範化している：</p><ul><li><strong>エネルギー排出基準</strong>：修練と生産過程で発生するエネルギー排出を厳格に制限する</li><li><strong>資源採掘基準</strong>：霊脈、鉱産、生物資源などの採掘を規範化し、過度な採掘を防止する</li><li><strong>生態保護レッドライン</strong>：生態保護レッドラインを画定し、レッドライン内ではいかなる破壊的活動も禁止する</li><li><strong>環境影響評価</strong>：重大な修練工事と建設プロジェクトは環境影響評価を実施しなければならない</li></ul><p>環境保護監管は専門の環境監管機構が責任を負い、共生ネットワークを通じて環境質量をリアルタイムで監視し、違法行為に対して厳しい処罰を行う。</p><h3 id="_3-2-汚染治理技術" tabindex="-1">3.2 汚染治理技術 <a class="header-anchor" href="#_3-2-汚染治理技術" aria-label="Permalink to &quot;3.2 汚染治理技術&quot;">​</a></h3><p>共生文明は先進的な汚染治理技術を発展させている：</p><ul><li><strong>エネルギー汚染治理</strong>：エネルギー濾過、エネルギー転化などの技術を通じて、修練活動が発生させたエネルギー汚染を治理する</li><li><strong>物質汚染治理</strong>：生物修復、化学処理、物理浄化などの技術を通じて、物質汚染を治理する</li><li><strong>法則汚染治理</strong>：法則剥離、法則中和などの技術を通じて、法則侵食が引き起こした環境汚染を治理する</li><li><strong>生態修復技術</strong>：生命循環体系と生態工学技術を通じて、損傷を受けた生態系を修復する</li></ul><h3 id="_3-3-資源の持続可能な利用" tabindex="-1">3.3 資源の持続可能な利用 <a class="header-anchor" href="#_3-3-資源の持続可能な利用" aria-label="Permalink to &quot;3.3 資源の持続可能な利用&quot;">​</a></h3><p>共生文明は資源の持続可能な利用を強調し、略奪式開発に反対する：</p><ul><li><strong>資源採掘割当</strong>：非再生可能資源に対して採掘割当制度を実施し、資源の長期的な利用を確保する</li><li><strong>資源循環利用</strong>：資源循環利用技術を大力に発展させ、資源利用効率を向上させる</li><li><strong>再生可能エネルギー開発</strong>：太陽エネルギー、風力エネルギー、水力エネルギー、エネルギー場エネルギーなどの再生可能エネルギーを積極的に開発する</li><li><strong>代替資源研究開発</strong>：希少資源の代替品を研究開発し、希少資源への依存を減らす</li></ul><h3 id="_3-4-生態保護と修復" tabindex="-1">3.4 生態保護と修復 <a class="header-anchor" href="#_3-4-生態保護と修復" aria-label="Permalink to &quot;3.4 生態保護と修復&quot;">​</a></h3><p>共生文明は生態保護と修復を高度に重視する：</p><ul><li><strong>自然保護区</strong>：各級の自然保護区を建立し、希少種と原始生態系を保護する</li><li><strong>生態修復工事</strong>：すでに破壊された生態系に対して修復を行い、生態平衡を回復する</li><li><strong>種保護計画</strong>：絶滅危惧種に対して保護と繁殖を行い、種の絶滅を防止する</li><li><strong>生態補償メカニズム</strong>：生態保護により損失を受けた地区と集団に対して補償を行う</li></ul><h2 id="第四節-居住可能空間建設" tabindex="-1">第四節 居住可能空間建設 <a class="header-anchor" href="#第四節-居住可能空間建設" aria-label="Permalink to &quot;第四節 居住可能空間建設&quot;">​</a></h2><p>共生文明は住居と環境保障の基礎の上に、居住可能空間建設を大力に推進する：</p><h3 id="_4-1-都市計画" tabindex="-1">4.1 都市計画 <a class="header-anchor" href="#_4-1-都市計画" aria-label="Permalink to &quot;4.1 都市計画&quot;">​</a></h3><p>共生文明の都市計画は「コンパクト、グリーン、スマート、人文」の原則に従う：</p><ul><li><strong>コンパクトレイアウト</strong>：都市はコンパクトレイアウトを採用し、土地占用と交通エネルギー消費を減らす</li><li><strong>グリーン空間</strong>：都市内に十分な緑地、公園、湿地などのグリーン空間を保留する</li><li><strong>スマート管理</strong>：アンカーネットワークとスマート技術を通じて、都市のスマート管理を実現する</li><li><strong>人文関懐</strong>：都市計画は異なる種族、異なる年齢、異なる能力集団の需要を十分に考慮する</li></ul><h3 id="_4-2-修練コミュニティ建設" tabindex="-1">4.2 修練コミュニティ建設 <a class="header-anchor" href="#_4-2-修練コミュニティ建設" aria-label="Permalink to &quot;4.2 修練コミュニティ建設&quot;">​</a></h3><p>共生文明は居住、修練、サービスを一体化した修練コミュニティを大力に建設する：</p><ul><li><strong>コミュニティ修練センター</strong>：各コミュニティには修練センターが設けられ、公共修練空間と修練指導を提供する</li><li><strong>コミュニティサービスセンター</strong>：医療、教育、商業、娯楽などの総合サービスを提供する</li><li><strong>コミュニティ緑地</strong>：コミュニティ内に十分な緑地とレジャー空間を保留する</li><li><strong>コミュニティ文化</strong>：コミュニティ文化を育成し、居住者の帰属感と凝集力を增强する</li></ul><h3 id="_4-3-跨位面居住可能空間" tabindex="-1">4.3 跨位面居住可能空間 <a class="header-anchor" href="#_4-3-跨位面居住可能空間" aria-label="Permalink to &quot;4.3 跨位面居住可能空間&quot;">​</a></h3><p>跨位面探索の推進に伴い、共生文明は他の位面に居住可能空間を建設し始める：</p><ul><li><strong>位面居住可能改造</strong>：条件の適した位面に対して居住可能改造を行い、新たな居住と修練空間を建設する</li><li><strong>生態移民</strong>：計画的に人口を資源緊張の位面から新開発の居住可能位面に移住させる</li><li><strong>跨位面住居</strong>：頻繁に跨位面旅行をする修練者向けに跨位面の住居保障を提供する</li></ul><h2 id="第五節-五種文明類型の住居と環境モデルの差異" tabindex="-1">第五節 五種文明類型の住居と環境モデルの差異 <a class="header-anchor" href="#第五節-五種文明類型の住居と環境モデルの差異" aria-label="Permalink to &quot;第五節 五種文明類型の住居と環境モデルの差異&quot;">​</a></h2><p>五種の共生文明類型は住居と環境モデルにおいてそれぞれ特色を持つ：</p><table tabindex="0"><thead><tr><th>類型</th><th>住居モデルの特徴</th><th>環境モデルの特徴</th></tr></thead><tbody><tr><td>東アジア集約型</td><td>高密度、集約化、集団寮を主とする</td><td>厳格な監管、高效な治理、快速な修復</td></tr><tr><td>北欧福利型</td><td>高保障、高品質、個性化</td><td>高基準、高投入、生態優先</td></tr><tr><td>北米多元型</td><td>市場化、多様化、低密度</td><td>市場化治理、技術駆動、資源保護</td></tr><tr><td>欧州大陸社会型</td><td>社会住宅、協同組合住宅、均衡配置</td><td>団体参与、協商治理、持続可能な発展</td></tr><tr><td>発展中超赶型</td><td>保障優先、快速建設、漸次改善</td><td>発展と保護を并重、重点治理</td></tr></tbody></table><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>住居と環境保障はアンカー共生文明の「民生の礎石」であり「生態の屏障」である。多層次の住居保障体系、全方位の環境保護体系、科学的な居住可能空間建設を通じて、共生文明は「居住者に家あり、生態共生、持続可能な発展、万族居住可能」の目標を実現した。住居の保障はすべての共生生命が安心して修練できるようにし、環境の保護は文明の長期的な発展のために生態基礎を築いた。両者は相辅相成し、共同で共生文明の万族共進と永续発展を支えている。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>45-住房保障法 (住居保障法)</li><li>46-环境保护法 (環境保護法)</li><li>32-北欧福利型文明 (北欧福利型文明)</li></ul>',59)])])}const b=a(i,[["render",n]]);export{p as __pageData,b as default};
